import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        long[] parent = new long[(int)p];
        for (int i = 0; i < p; i++) {
            parent[i] = i;
        }
        Set<Long> s = new HashSet<>();
        s.add(0L);
        long answer = 1;
        final long MOD = 1000000007;

        if (k == 0) {
            for (long i = 1; i < p; i++) {
                answer = (answer * p) % MOD;
            }
            System.out.println(answer);
            return;
        }

        for (long i = 0; i < p; i++) {
            long target = (k * i) % p;
            long root_i = i;
            long root_target = target;

            while (parent[(int)root_i] != root_i) {
                root_i = parent[(int)root_i];
            }
            while (parent[(int)root_target] != root_target) {
                root_target = parent[(int)root_target];
            }
            parent[(int)root_i] = root_target;
        }

        int[] count = new int[(int)p];
        for (long i = 0; i < p; i++) {
            long root = i;
            while (parent[(int)root] != root) {
                root = parent[(int)root];
            }
            count[(int)root]++;
        }

        for (int i = 1; i < p; i++) {
            if (count[i] > 0) {
                answer = (answer * p) % MOD;
            }
        }

        if (k == 1) {
            answer = (answer * p) % MOD;
        }

        System.out.println(answer);
    }
}
